/**
 * Test flow for submitCatalogItemRequest action
 * Demonstrates submitting a catalog item request
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testSubmitCatalogItemRequest = Flow(
    {
        $id: Now.ID['test_submit_catalog_item_request_flow'],
        name: 'Test Submit Catalog Item Request',
        description: 'Tests the submitCatalogItemRequest core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_submit_catalog_item_request_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (__params) => {
        const result = wfa.action(
            action.core.submitCatalogItemRequest,
            { $id: Now.ID['test_submit_catalog_item_request_action'] },
            {
                catalog_item: 'sample_catalog_item_sys_id',
                sysparm_quantity: 1,
                catalog_item_inputs: 'variable1=value1^variable2=value2',
                wait_for_completion: false,
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_submit_catalog_item_request_log'] },
            {
                log_level: 'info',
                log_message: `submitCatalogItemRequest outputs: requested_item=${(result as any).requested_item}, status=${(result as any).status}, error_message=${(result as any).error_message}`,
            }
        )
    }
)
